import { BoxMeter } from '@/components/ui/BoxMeter.js';
import { Icon } from '@/components/ui/Icon.js';
import { cx } from '@/lib/cx.js';
import type { MomentCopy } from './copy.js';
import styles from './Badge.module.css';

/**
 * The summary's seal when the session was a moment: a gold ring that draws
 * itself around the moment's mark (a flame for a streak, the full box meter
 * for mastery, the notebook for words, a sparkle for a first). Under reduced
 * motion the ring is drawn and nothing pops.
 */
export function Badge({
  icon,
  className,
}: {
  icon: MomentCopy['icon'];
  className?: string;
}): React.JSX.Element {
  return (
    <span className={cx(styles.badge, className)} aria-hidden="true">
      <svg className={styles.ring} viewBox="0 0 52 52">
        <circle className={styles.track} cx="26" cy="26" r="24" />
        <circle className={styles.draw} cx="26" cy="26" r="24" />
      </svg>
      {icon === 'boxes' ? (
        <BoxMeter box={5} className={styles.meter} />
      ) : (
        <Icon name={icon} size={34} weight={2.4} className={styles.icon} />
      )}
    </span>
  );
}
